import controller.JogoController;import model.Cores;import model.Entrada;import util.DadosService;import util.SaveService;import view.MenuView;
public class Main {public static void main(String[]args){DadosService.carregarMonstros();while(true){boolean save=SaveService.existeSave();int op=MenuView.menuInicial(save);if(op==1)new JogoController().iniciarNovoJogo();else if(op==2){if(!save)System.out.println(Cores.aviso("Nenhum jogo salvo foi encontrado."));else{SaveService.DadosSave s=SaveService.carregar();if(s!=null)new JogoController().iniciarCarregado(s);}}else if(op==3){System.out.println(Cores.ciano("Ate a proxima aventura em Aethoria!"));break;}else System.out.println(Cores.aviso("Opcao invalida. Escolha 1, 2 ou 3."));}}}
